shots.draw_js:
clearScene();setBig(null);
setEq("$$\\pi_{i+1}=\\varepsilon\\text{-greedy}(Q^{\\pi_i})$$","top");
note("有 ε 概率在乱走",640,300,"r lg");
setCap("L2 的策略改进定理要求<b>贪心</b>。现在贪心被换掉了 —— <b>改进还成立吗？</b>");

clearScene();setEq(null);
setBig("随机化会拖累改进","毕竟有 ε 的概率在做蠢事");
setCap("这个担心很具体：新策略<b>确实</b>有 ε 的概率去走更差的动作。");

clearScene();setBig(null);
setEq("$$Q^{\\pi}(s,\\pi'(s))=\\frac{\\varepsilon}{|A|}\\sum_a Q^{\\pi}(s,a)+(1-\\varepsilon)\\max_a Q^{\\pi}(s,a)$$","top");
note("两支分别算，再相加",640,320,"y lg");
setCap("先把新策略下的 Q 拆成两支：<b>随机那一支求平均，贪心那一支取最大</b>。");

clearScene();setBig(null);
setEq("$$\\max_a Q^{\\pi}(s,a)\\;\\ge\\;\\sum_a \\frac{\\pi(a\\mid s)-\\varepsilon/|A|}{1-\\varepsilon}\\,Q^{\\pi}(s,a)$$","top");
note("max ≥ 任何凸组合",640,320,"y lg");
setCap("窍门：<b>最大值不小于任何一个凸组合</b>。关键是证出这组权重确实是凸组合。");

clearScene();setBig(null);
setEq("$$\\sum_a\\Big(\\pi(a\\mid s)-\\tfrac{\\varepsilon}{|A|}\\Big)=1-\\varepsilon \\;\\Longrightarrow\\; \\sum_a w_a=1$$","top");
lamps({y:330,gap:330,items:[
  {label:"非负",sub:"π(a|s) ≥ ε/|A| 恒成立",state:"on"},
  {label:"和为 1",sub:"(1−ε)/(1−ε)",state:"on"},
  {label:"所以是凸组合",sub:"不等式成立",state:"on"}]});
setCap("两条都成立：<b>ε-greedy 保证每个动作的概率都 ≥ ε/|A|</b>，所以权重非负。");

clearScene();setBig(null);
setEq("$$Q^{\\pi}(s,\\pi'(s))\\;\\ge\\;\\sum_a \\pi(a\\mid s)\\,Q^{\\pi}(s,a)\\;=\\;V^{\\pi}(s)$$","top");
note("ε/|A| 那两项抵消",640,320,"g lg");
setCap("代回去，<b>ε/|A| 的两项正好抵消</b>，剩下的恰好是 V^π(s)。改进成立。");

clearScene();setBig(null);setEq(null);
lamps({y:270,gap:300,items:[
  {label:"单调改进",sub:"成立，已证",state:"on"},
  {label:"前提：Q^π 精确",sub:"讲座假定，实际做不到",state:"dead"},
  {label:"前提：ε 固定",sub:"而算法里 ε 在衰减",state:"dead"}]});
note("两个前提都被静默使用",640,420,"r");
setCap("<b>指名反驳</b>：改进不受随机化影响。但这条证明有<b>两个没被点名的前提</b>。");

clearScene();setBig(null);setEq(null);
note("ε 该取多少？",640,260,"y lg");
note("该不该随时间变？",640,320,"y lg");
setCap("ε 看起来像个超参数 —— 调一个值就完事。<b>它不是。</b>");

clearScene();setEq(null);
setBig("ε 是个超参数","取个 0.1 之类的折中值就好");
setCap("固定 ε 在实践里到处都是 —— 而它<b>保证</b>了你拿不到最优策略。");

clearScene();setBig(null);setEq(null);
lamps({y:290,gap:340,items:[
  {label:"无限探索",sub:"每个 (s,a) 被访问无穷多次",state:"on"},
  {label:"渐近贪心",sub:"策略最终收敛到贪心",state:"on"}]});
note("GLIE：两条缺一不可",640,420,"y");
setCap("<b>GLIE</b> = Greedy in the Limit with Infinite Exploration。两条<b>同时</b>要。");

clearScene();setBig(null);setEq(null);
fillBars({order:[0,1,2],step:560,vals:[5.082,15.976,27.573],x:380,y:420,w:520,h:160,max:30,
  label:function(i){return ["ε=0.1","ε=0.3","ε=0.5"][i];},
  cls:function(i){return "r";},
  fmt:function(v){return v.toFixed(2);}});
note("与最优的差距",640,466,"y");
setCap("火星车实测：固定 ε 的策略<b>永远</b>比最优差这么多，训练多久都不变。");

clearScene();setBig(null);
setEq("$$\\varepsilon_k=\\frac{1}{k}:\\qquad \\sum_k \\varepsilon_k=\\infty \\quad\\text{and}\\quad \\varepsilon_k\\to 0$$","top");
fillBars({order:[0,1,2,3],step:560,vals:[2.929,5.187,7.485,9.788],x:380,y:430,w:520,h:150,max:11,
  label:function(i){return ["K=10","K=100","K=1e3","K=1e4"][i];},
  cls:function(i){return "g";},
  fmt:function(v){return v.toFixed(2);}});
note("Σ 1/k 一直在涨",640,466,"g");
setCap("<b>ε_k = 1/k 同时满足两条</b>：调和级数发散（无限探索），且 1/k → 0（渐近贪心）。");

clearScene();setBig(null);setEq(null);
lamps({y:270,gap:300,items:[
  {label:"ε 固定",sub:"探索够，但永不贪心",state:"dead"},
  {label:"ε_k = 1/k²",sub:"衰减了，但探索不够",state:"dead"},
  {label:"ε_k = 1/k",sub:"两条都满足",state:"on"}]});
note("衰减快慢是两难",640,420,"y");
setCap("<b>指名反驳</b>：ε 不是超参数，是收敛条件。<b>衰减太慢太快都不行。</b>");

clearScene();setBig(null);setEq(null);
note("SARSA：用实际走的 a′",640,270,"b lg");
note("Q-learning：用 max",640,330,"v lg");
setCap("两条更新式，只有方括号里的<b>目标</b>不同。看起来像实现细节。");

clearScene();setEq(null);
setBig("差别只是写法","反正都收敛到 Q*");
setCap("两者确实都收敛到 Q*。<b>但它们在收敛前学的不是同一个东西。</b>");

clearScene();setBig(null);
setEq("$$\\text{SARSA: } r+\\gamma Q(s',a') \\qquad \\text{Q-learning: } r+\\gamma \\max_a Q(s',a)$$","top");
note("a′ 是抽出来的",400,320,"b lg");
note("max 与实际无关",880,320,"v lg");
setCap("SARSA 的目标<b>取决于你实际怎么走</b>；Q-learning 的不取决于。");

clearScene();setBig(null);
setEq("$$r=0,\\ \\gamma=0.9,\\ Q(s',a_{\\text{greedy}})=10,\\ Q(s',a_{\\text{taken}})=2$$","top");
fillBars({order:[0,1],step:700,vals:[1.8,9.0],x:400,y:430,w:480,h:160,max:10,
  label:function(i){return ["SARSA 目标","Q-learning 目标"][i];},
  cls:function(i){return i===0?"b":"v";},
  fmt:function(v){return v.toFixed(1);}});
note("同一笔转移",640,466,"y");
setCap("同一笔数据，两个目标差 <b>7.2</b>。这不是写法差别。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:330,items:[
  {label:"SARSA",sub:"on-policy · 学含探索的策略",state:"on"},
  {label:"Q-learning",sub:"off-policy · 学贪心策略",state:"on"},
  {label:"悬崖行走",sub:"两者选出的路不同",state:"on"}]});
note("差别在学谁的值",640,420,"y");
setCap("<b>指名反驳</b>：不是写法，是 <b>on-policy 与 off-policy</b> —— 学的是两个策略的值。");
